-- SELECT-only public spell-definition capture; local peq, 2026-11-12.
SELECT JSON_OBJECT('id',id,'name',name,'good_effect',goodEffect,'cast_time',cast_time,'buff_duration_formula',buffdurationformula,'buff_duration',buffduration,'effects',JSON_ARRAY(JSON_ARRAY(effectid1,effect_base_value1,formula1,max1),JSON_ARRAY(effectid2,effect_base_value2,formula2,max2),JSON_ARRAY(effectid3,effect_base_value3,formula3,max3),JSON_ARRAY(effectid4,effect_base_value4,formula4,max4),JSON_ARRAY(effectid5,effect_base_value5,formula5,max5),JSON_ARRAY(effectid6,effect_base_value6,formula6,max6),JSON_ARRAY(effectid7,effect_base_value7,formula7,max7),JSON_ARRAY(effectid8,effect_base_value8,formula8,max8),JSON_ARRAY(effectid9,effect_base_value9,formula9,max9),JSON_ARRAY(effectid10,effect_base_value10,formula10,max10),JSON_ARRAY(effectid11,effect_base_value11,formula11,max11),JSON_ARRAY(effectid12,effect_base_value12,formula12,max12)))
FROM spells_new WHERE goodEffect=0 AND buffdurationformula>0 AND ((effectid1 IN (0,334) AND effect_base_value1<0) OR (effectid2 IN (0,334) AND effect_base_value2<0) OR (effectid3 IN (0,334) AND effect_base_value3<0) OR (effectid4 IN (0,334) AND effect_base_value4<0) OR (effectid5 IN (0,334) AND effect_base_value5<0) OR (effectid6 IN (0,334) AND effect_base_value6<0) OR (effectid7 IN (0,334) AND effect_base_value7<0) OR (effectid8 IN (0,334) AND effect_base_value8<0) OR (effectid9 IN (0,334) AND effect_base_value9<0) OR (effectid10 IN (0,334) AND effect_base_value10<0) OR (effectid11 IN (0,334) AND effect_base_value11<0) OR (effectid12 IN (0,334) AND effect_base_value12<0)) ORDER BY id;
